    private RecordChart trackingChart(View root){if(root instanceof RecordChart)return (RecordChart)root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){RecordChart found=trackingChart(group.getChildAt(n));if(found!=null)return found;}return null;}
    private View trackingControl(View root,String label){if(root.getContentDescription()!=null&&label.contentEquals(root.getContentDescription())||root instanceof TextView text&&label.contentEquals(text.getText()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View found=trackingControl(group.getChildAt(n),label);if(found!=null)return found;}return null;}
    private void trackingTap(TrackingActivity owner,String label){android.graphics.Rect[] target={null};phoneWait("Focused enabled real tracking control: "+label,()->{View root=owner.getWindow().getDecorView(),view=trackingControl(root,label);if(!ready(owner,root)||view==null||!view.isClickable()||!view.isEnabled())return false;android.graphics.Rect rect=new android.graphics.Rect();if(!view.getGlobalVisibleRect(rect)||rect.height()!=view.getHeight()||rect.width()!=view.getWidth())return false;assertTrue(rect.height()>=Design.dp(context,48));assertTrue(rect.width()>=Design.dp(context,48));target[0]=rect;return true;});assertTrue("Exactly one measured control input",device.click(target[0].centerX(),target[0].centerY()));}
    private PhoneMotionChartReader.Data trackingLoaded(TrackingActivity owner,long start,PhoneMotionChartReader.Data previous){PhoneMotionChartReader.Data[] result={null};phoneWait("Real Activity tick publishes a new owned phone chart",()->{RecordChart chart=trackingChart(owner.getWindow().getDecorView());PhoneMotionChartReader.Data data=chart==null?null:chart.renderedLiveData();if(!ready(owner,owner.getWindow().getDecorView())||data==null||data==previous||data.start!=start||data.bars.isEmpty())return false;result[0]=data;return true;});return result[0];}
    private void trackingBounds(TrackingActivity owner){instrumentation.runOnMainSync(()->{View root=owner.getWindow().getDecorView();assertTrue(ready(owner,root));RecordChart chart=trackingChart(root);assertNotNull(chart);android.graphics.Rect plot=new android.graphics.Rect();assertTrue(chart.getGlobalVisibleRect(plot));assertEquals(chart.getHeight(),plot.height());assertEquals(chart.getWidth(),plot.width());View pause=trackingControl(root,"Pause tracking");if(pause==null)pause=trackingControl(root,"Resume tracking");assertNotNull(pause);View stop=trackingControl(root,"Stop tracking"),more=trackingControl(root,"Tracking options");assertNotNull(stop);assertNotNull(more);android.graphics.Rect pauseBounds=new android.graphics.Rect(),stopBounds=new android.graphics.Rect();assertTrue(pause.getGlobalVisibleRect(pauseBounds));assertTrue(stop.getGlobalVisibleRect(stopBounds));for(View view:new View[]{pause,stop,more}){android.graphics.Rect rect=new android.graphics.Rect();assertTrue(view.isEnabled()&&view.isClickable());assertTrue(view.getGlobalVisibleRect(rect));assertEquals(view.getHeight(),rect.height());assertEquals(view.getWidth(),rect.width());assertTrue(rect.height()>=Design.dp(context,48));assertTrue(rect.width()>=Design.dp(context,48));assertTrue(rect.bottom<=root.getHeight()-root.getRootWindowInsets().getInsets(WindowInsets.Type.navigationBars()).bottom);}assertTrue("Full chart clears fixed Pause footer",plot.bottom<=pauseBounds.top);assertTrue(pauseBounds.bottom<=stopBounds.top);});}
