    private boolean ready(Activity a,View decor){return !a.isDestroyed()&&!a.isFinishing()&&ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED).contains(a)&&a.getWindow().getDecorView()==decor&&a.hasWindowFocus()&&decor.hasWindowFocus()&&decor.isAttachedToWindow()&&decor.isLaidOut()&&decor.getWidth()>0&&decor.getHeight()>0;}
    private void focusChart(Activity owner,RecordChart chart){long until=SystemClock.elapsedRealtime()+8000;boolean[] valid={false};while(!valid[0]&&SystemClock.elapsedRealtime()<until){instrumentation.runOnMainSync(()->{View decor=owner.getWindow().getDecorView();if(ready(owner,decor)&&chart.getRootView()==decor&&chart.isAttachedToWindow()&&chart.isLaidOut()&&chart.getWidth()>0&&chart.getHeight()>0){
            // A new content tree cannot take keyboard focus before attachment/layout.
            // Use the platform focus request to leave touch mode, not a test-only
            // focusable flag or a removed retention assertion.
            valid[0]=chart.requestFocusFromTouch()&&chart.hasFocus();
        }});if(!valid[0])SystemClock.sleep(50);}assertTrue("The focused resumed owner must give its actual laid-out chart keyboard focus",valid[0]);}
    private void capture(Activity a,String name)throws Exception{
        long until=SystemClock.elapsedRealtime()+8000;boolean committed=false;
        while(!committed&&SystemClock.elapsedRealtime()<until){CountDownLatch frame=new CountDownLatch(1);View[] root={null};instrumentation.runOnMainSync(()->{View decor=a.getWindow().getDecorView();if(ready(a,decor)){assertTrue(decor.isHardwareAccelerated());root[0]=decor;decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();}});if(root[0]==null){SystemClock.sleep(50);continue;}if(!frame.await(1,TimeUnit.SECONDS))continue;device.waitForIdle();boolean[] valid={false};instrumentation.runOnMainSync(()->valid[0]=ready(a,root[0]));committed=valid[0];}
        assertTrue("Focused fixture frame must commit: "+name,committed);File folder=new File(context.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"chart-clock-"+name+".png")));
    }
    private List<JSONObject> samples(long start,long end,long cadence)throws Exception{List<JSONObject> values=new ArrayList<>();int count=(int)((end-start)/cadence);for(int n=1;n<=count;n++){JSONObject value=new JSONObject().put("start",start+(n-1)*cadence).put("time",start+n*cadence);if(n<count/3||n>count/3+Math.max(1,count/20))value.put("movement",n%19==0?0:.02+.09*(1+Math.sin(n*.19))+.1*(n%47<3?1:0));values.add(value);}return values;}
    private RecordChart render(Activity a,String title,List<JSONObject> values,long start,long end,ZoneId zone,boolean night){RecordChart[] chart={null};instrumentation.runOnMainSync(()->{LinearLayout body=Design.page(a,false,null,null);Design.header(body,title,null);Design.text(body,"VISUAL TEST · synthetic measurements in memory",11,600,Design.BROWN);Design.space(body,20);LinearLayout panel=Design.col(a);Design.pad(panel,night?12:0,night?12:0);if(night)panel.setBackground(Design.shape(a,Design.PLUM,20));Design.text(panel,"Recorded movement",16,600,night?Design.LILAC:Design.INK);Design.space(panel,12);chart[0]=new RecordChart(a,values,"movement",start,end,night,zone);panel.addView(chart[0],new LinearLayout.LayoutParams(-1,Design.dp(a,230)));body.addView(panel);Design.space(body,16);Design.text(body,"Missing intervals stay blank. Tap a column to inspect its measured interval.",13,400,Design.MUTED);});focusChart(a,chart[0]);return chart[0];}
    private void phoneWait(String label,java.util.function.BooleanSupplier condition){long until=SystemClock.elapsedRealtime()+8000;boolean[] yes={false};while(!yes[0]&&SystemClock.elapsedRealtime()<until){instrumentation.runOnMainSync(()->yes[0]=condition.getAsBoolean());if(!yes[0])SystemClock.sleep(25);}assertTrue(label,yes[0]);}
    private PhoneMotionChartReader.Data phoneLoaded(Activity owner,RecordChart chart,long end){return phoneLoaded(owner,chart,end,null);}
    private PhoneMotionChartReader.Data phoneLoaded(Activity owner,RecordChart chart,long end,PhoneMotionChartReader.Data previous){phoneWait("Actual phone history must settle with full chart bounds",()->{PhoneMotionChartReader.Data data=chart.renderedLiveData();android.graphics.Rect bounds=new android.graphics.Rect();return ready(owner,owner.getWindow().getDecorView())&&chart.isAttachedToWindow()&&chart.isLaidOut()&&chart.getGlobalVisibleRect(bounds)&&bounds.width()==chart.getWidth()&&bounds.height()==chart.getHeight()&&data!=null&&data!=previous&&data.end==end;});PhoneMotionChartReader.Data[] result={null};instrumentation.runOnMainSync(()->result[0]=chart.renderedLiveData());return result[0];}
    private void exactPhoneBars(PhoneMotionChartReader.Data data,List<JSONObject> rows){List<ChartSeries.Sample> samples=new ArrayList<>();int measured=0;for(JSONObject row:rows){long time=row.optLong("time");Double value=row.isNull("movement")?null:row.optDouble("movement");samples.add(new ChartSeries.Sample(row.isNull("start")?null:row.optLong("start"),time,value));if(value!=null&&Double.isFinite(value)&&value>=0&&time>=data.start&&time<=data.end)measured++;}List<ChartSeries.Bar> expected=ChartSeries.aggregate(samples,data.start,data.end,data.columns);assertEquals(measured,data.readings);assertEquals(expected.size(),data.bars.size());for(int n=0;n<expected.size();n++){ChartSeries.Bar a=expected.get(n),b=data.bars.get(n);assertEquals(a.from,b.from);assertEquals(a.to,b.to);assertEquals(a.readings,b.readings);assertEquals(a.value,b.value,0);}}
    /** Same production loader/apply path on a real focused RecordChart, with no TrackingService or sensor. */
    private void phoneHistory(Activity owner,String database)throws Exception{
        long start=Instant.parse("2026-10-22T22:00:00Z").toEpochMilli();long[] id={2},from={start},end={start+1800000};String[] phase={"ACTIVE"};AtomicReference<List<JSONObject>> pending=new AtomicReference<>(List.of());RecordChart[] chart={null};AtomicInteger opens=new AtomicInteger();AtomicBoolean failRead=new AtomicBoolean();AtomicReference<CountDownLatch> hold=new AtomicReference<>(),entered=new AtomicReference<>();
        try(Store store=new Store(context,database)){android.database.sqlite.SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{db.execSQL("INSERT INTO sessions(id,start,source,origin,zone) VALUES(2,?,'tracked','local','UTC')",new Object[]{start});db.execSQL("INSERT INTO sessions(id,start,source,origin,zone) VALUES(3,?,'tracked','local','UTC')",new Object[]{start+3600000});db.execSQL("INSERT INTO sessions(id,start,source,origin,zone) VALUES(4,?,'tracked','local','UTC')",new Object[]{start});
            // >one page; equal time straddles the page boundary, null and an explicit time gap stay blank.
            for(int n=1;n<=1800;n++){long time=start+n*1000L;Double movement=null;if(n<=120)movement=0d;else if(n<601||n>720)movement=.02+(n%17)*.01;store.epoch(2,start+(n-1)*1000L,time,movement,null,null,1);if(n==1024)store.epoch(2,time,time,.7,null,null,1);}
            db.delete("epochs","session=2 AND time>? AND time<=?",new String[]{""+(start+1200000),""+(start+1260000)});store.epoch(3,start+3600000,start+3660000,.6,null,null,1);
            for(int n=1;n<=5000;n++)store.epoch(4,start+(n-1)*1000L,start+n*1000L,n%2==0?.1:null,null,null,n%2==0?1:0);db.setTransactionSuccessful();}finally{db.endTransaction();}}
        phoneReader=new PhoneMotionChartReader(owner,c->{assertNotEquals("DB opens must never execute on main",Looper.getMainLooper(),Looper.myLooper());assertEquals("SleepWell-phone-chart",Thread.currentThread().getName());opens.incrementAndGet();CountDownLatch gate=hold.getAndSet(null);if(gate!=null){CountDownLatch signal=entered.get();if(signal!=null)signal.countDown();try{assertTrue("Held private read must be released",gate.await(8,TimeUnit.SECONDS));}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new CancellationException();}}if(failRead.get())throw new IllegalStateException("Injected private phone-history failure");return new Store(c,database);},(session,begin,state,view)->session==id[0]&&begin==from[0]&&state.equals(phase[0])&&view==chart[0]);
        Runnable request=()->phoneReader.request(id[0],from[0],end[0],phase[0],pending.get(),chart[0]);
        instrumentation.runOnMainSync(()->{LinearLayout body=Design.page(owner,false,null,null);Design.header(body,"Phone movement history",null);Design.text(body,"VISUAL TEST · seeded private measurements · no recording",11,600,Design.BROWN);Design.space(body,20);LinearLayout panel=Design.col(owner);Design.pad(panel,12,12);panel.setBackground(Design.shape(owner,Design.PLUM,20));Design.text(panel,"Recorded movement",16,600,Design.LILAC);chart[0]=new RecordChart(owner,List.of(),"movement",start,end[0],true,ZoneOffset.UTC);chart[0].liveSource(request);panel.addView(chart[0],new LinearLayout.LayoutParams(-1,Design.dp(owner,230)));body.addView(panel);Design.space(body,16);Design.text(body,"Private SQLite history. Actual zero, missing values and pause gaps remain distinct.",13,400,Design.MUTED);});focusChart(owner,chart[0]);instrumentation.runOnMainSync(request);PhoneMotionChartReader.Data first=phoneLoaded(owner,chart[0],end[0]);List<JSONObject> baseline;try(Store store=new Store(context,database)){baseline=store.rows("SELECT start,time,movement FROM epochs WHERE session=2 ORDER BY time,id");}exactPhoneBars(first,baseline);assertTrue(first.bars.stream().anyMatch(b->b.value==0));assertFalse(first.bars.stream().anyMatch(b->b.from<start+650000&&b.to>start+650000));assertFalse(first.bars.stream().anyMatch(b->b.from<start+1230000&&b.to>start+1230000));capture(owner,"phone-history");
        Long[] inspected={null};instrumentation.runOnMainSync(()->{assertTrue(chart[0].performAccessibilityAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD,null));assertTrue(chart[0].onKeyDown(KeyEvent.KEYCODE_DPAD_RIGHT,new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_RIGHT)));inspected[0]=chart[0].inspectedTime();assertTrue(chart[0].getContentDescription().toString().startsWith("movement at "));});
        // Snapshot pending overlaps the newly durable checkpoint. The real reader excludes the duplicate.
        JSONObject overlap=new JSONObject().put("start",end[0]-1000).put("time",end[0]).put("movement",42),tail=new JSONObject().put("start",end[0]).put("time",end[0]+1000).put("movement",.9);pending.set(List.of(overlap,tail));instrumentation.runOnMainSync(()->{end[0]+=1000;request.run();try{tail.put("movement",42);}catch(org.json.JSONException invalid){throw new AssertionError(invalid);}});PhoneMotionChartReader.Data tailData=phoneLoaded(owner,chart[0],end[0]);List<JSONObject> expected=new ArrayList<>(baseline);expected.add(new JSONObject().put("start",start+1800000).put("time",start+1801000).put("movement",.9));exactPhoneBars(tailData,expected);instrumentation.runOnMainSync(()->{assertEquals(inspected[0],chart[0].inspectedTime());assertTrue(chart[0].hasFocus());assertTrue(chart[0].isAttachedToWindow());});capture(owner,"phone-selected");
        try(Store store=new Store(context,database)){store.epoch(2,start+1800000,start+1801000,.9,null,null,1);}instrumentation.runOnMainSync(()->{phoneReader.suspend();phase[0]="PAUSED";request.run();});PhoneMotionChartReader.Data paused=phoneLoaded(owner,chart[0],end[0],tailData);exactPhoneBars(paused,expected);instrumentation.runOnMainSync(()->{assertEquals(inspected[0],chart[0].inspectedTime());assertTrue(chart[0].hasFocus());});capture(owner,"phone-paused");
        // A blocked read cannot delay main input; many updates coalesce and stale phase/owner results cannot apply.
        CountDownLatch release=new CountDownLatch(1),reading=new CountDownLatch(1);hold.set(release);entered.set(reading);int before=opens.get();instrumentation.runOnMainSync(request);assertTrue(reading.await(8,TimeUnit.SECONDS));try{instrumentation.runOnMainSync(()->{for(int n=0;n<100;n++)request.run();phoneReader.suspend();phase[0]="ACTIVE";end[0]+=1000;pending.set(List.of());request.run();});}finally{release.countDown();}phoneLoaded(owner,chart[0],end[0]);assertTrue("Only running + newest request may open DB",opens.get()-before<=2);
        failRead.set(true);instrumentation.runOnMainSync(request);phoneWait("Actual worker error must be explicit",()->chart[0].renderedLiveData()==null&&chart[0].getContentDescription().toString().contains("unavailable. Tap to retry"));instrumentation.runOnMainSync(()->assertEquals(inspected[0],chart[0].inspectedTime()));capture(owner,"phone-retry");failRead.set(false);instrumentation.runOnMainSync(()->assertTrue(chart[0].onKeyDown(KeyEvent.KEYCODE_ENTER,new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_ENTER))));phoneLoaded(owner,chart[0],end[0]);instrumentation.runOnMainSync(()->{assertEquals(inspected[0],chart[0].inspectedTime());assertTrue(chart[0].hasFocus());});
        // Oversized evidence is not reported as absent. No synthetic aggregate or dropped-gap fallback.
        instrumentation.runOnMainSync(()->{id[0]=4;end[0]=start+5000000;request.run();});phoneWait("Pathological detail must have an honest error",()->chart[0].renderedLiveData()==null&&chart[0].getContentDescription().toString().contains("too detailed"));
        instrumentation.runOnMainSync(()->{phoneReader.suspend();id[0]=2;end[0]=start+1802000;request.run();});phoneLoaded(owner,chart[0],end[0]);
        CountDownLatch staleRelease=new CountDownLatch(1),staleReading=new CountDownLatch(1);hold.set(staleRelease);entered.set(staleReading);instrumentation.runOnMainSync(request);assertTrue(staleReading.await(8,TimeUnit.SECONDS));try{instrumentation.runOnMainSync(()->{phoneReader.suspend();id[0]=3;from[0]=start+3600000;end[0]=start+3660000;});}finally{staleRelease.countDown();}instrumentation.waitForIdleSync();instrumentation.runOnMainSync(()->assertEquals("Replaced session must not receive a stale apply",start+1802000,chart[0].renderedLiveData().end));
        instrumentation.runOnMainSync(phoneReader::close);phoneReader.awaitClosed(8000);instrumentation.runOnMainSync(()->assertEquals(start+1802000,chart[0].renderedLiveData().end));assertFalse("No tracking service was started",TrackingService.running);assertFalse(AlarmService.active);
    }
    @Test public void alignedClocksElapsedSecondsAndFoldSelectionRenderWithoutEffects()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(Prefs.flag(context,"ringing"));assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(context,"tracking"));assertFalse(Prefs.flag(context,"trackingPaused"));
        Map<String,?> before=new HashMap<>(Prefs.of(context).getAll());String database="sleepwell-chart-clock-"+UUID.randomUUID()+".db";Records.Factory previous=Records.factory;Activity[] owner={null};boolean[] touchMode={true},capturedMode={false};
        try{
            Records.factory=c->new Store(c,database);try(Store store=new Store(context,database)){store.getWritableDatabase().execSQL("INSERT INTO sessions(id,start,end,active_ms,note,source,origin,zone) VALUES(1,1000,2000,1000,'Isolated chart owner','tracked','local','UTC')");}
            Instrumentation.ActivityMonitor monitor=instrumentation.addMonitor(RecordReportActivity.class.getName(),null,false);try{context.startActivity(new Intent(context,RecordReportActivity.class).putExtra("record",1L).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));owner[0]=monitor.waitForActivityWithTimeout(8000);assertNotNull(owner[0]);}finally{instrumentation.removeMonitor(monitor);}
            ((RecordReportActivity)owner[0]).awaitReaders(8000);instrumentation.waitForIdleSync();
            instrumentation.runOnMainSync(()->{touchMode[0]=owner[0].getWindow().getDecorView().isInTouchMode();capturedMode[0]=true;});
            ZoneId utc=ZoneOffset.UTC;long start=Instant.parse("2026-10-22T22:48:00Z").toEpochMilli(),end=Instant.parse("2026-10-23T06:30:00Z").toEpochMilli();List<JSONObject> overnight=samples(start,end,60000);RecordChart chart=render(owner[0],"Overnight clock axis",overnight,start,end,utc,false);
            instrumentation.runOnMainSync(()->{assertTrue(chart.performAccessibilityAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD,null));String selected=chart.getContentDescription().toString();assertTrue(selected.contains("movement at"));chart.updateData(overnight,end);assertEquals(selected,chart.getContentDescription().toString());assertTrue(chart.hasFocus());assertTrue(chart.isAttachedToWindow());});capture(owner[0],"overnight");
            render(owner[0],"Live signal clock axis",overnight,start,end,utc,true);capture(owner[0],"night");
            long shortEnd=start+21321;render(owner[0],"Short measured signal",samples(start,shortEnd,1000),start,shortEnd,utc,false);capture(owner[0],"short");
            ZoneId berlin=ZoneId.of("Europe/Berlin");long foldStart=ZonedDateTime.parse("2026-10-25T00:30:00+02:00[Europe/Berlin]").toInstant().toEpochMilli(),foldEnd=ZonedDateTime.parse("2026-10-25T03:30:00+01:00[Europe/Berlin]").toInstant().toEpochMilli();RecordChart fold=render(owner[0],"Repeated hour",samples(foldStart,foldEnd,60000),foldStart,foldEnd,berlin,false);
            instrumentation.runOnMainSync(()->{boolean first=false,second=false;while(fold.performAccessibilityAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD,null)){String label=fold.getContentDescription().toString();first|=label.contains("+02:00");second|=label.contains("+01:00");if(first&&second)break;}assertTrue("First occurrence must expose its UTC offset",first);assertTrue("Repeated occurrence must expose its distinct UTC offset",second);});capture(owner[0],"fold");phoneHistory(owner[0],database);trackingOwner(database);assertEquals("Chart fixture must not write personal preferences",before,Prefs.of(context).getAll());
        }finally{
            boolean drained=false;try{if(phoneReader!=null)instrumentation.runOnMainSync(phoneReader::close);if(owner[0]!=null){instrumentation.runOnMainSync(owner[0]::finish);long until=SystemClock.elapsedRealtime()+8000;while(!owner[0].isDestroyed()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(owner[0].isDestroyed());((RecordReportActivity)owner[0]).awaitReaders(8000);}if(phoneReader!=null)phoneReader.awaitClosed(8000);drained=true;}finally{if(drained&&trackingDrained){Records.factory=previous;assertTrue(context.deleteDatabase(database));}if(capturedMode[0])instrumentation.setInTouchMode(touchMode[0]);assertEquals("Chart cleanup must not write personal preferences",before,Prefs.of(context).getAll());}
        }
    }
